class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return "..."
    def intro(self):
        return f"{self.name}: {self.speak()}"

class Dog(Animal):
    def speak(self):
        return "멍"

class Puppy(Dog):
    def __init__(self, name, age):
        super().__init__(name)
        self.age = age

d = Dog("초코")
p = Puppy("보리", 1)
print(d.intro(), "|", p.intro())
print(isinstance(p, Animal), issubclass(Puppy, Animal))
